import math

def gcd(a, b):
    return math.gcd(a, b)

def C(x):
    if x <= 1:
        return 0
    count = 0
    for A in range(1, x):
        g = gcd(A, x)
        A_prime = A // g

        # Check if A' divides g
        if g % A_prime == 0:
            count += 1

    return count

# Test for x = 1 to 100
results = {}
for x in range(1, 101):
    results[x] = C(x)

# Print the results in a readable format
print("x | C(x)")
print("-" * 15)
for x, c in results.items():
    print(f"{x:2} | {c}")
